// Loads pages generated by ReactPreviewBundlerCheck in headless Chromium with the network
// cut off, and checks rendering, interaction, CSP and error reporting.
// Usage: node browser-check.cjs <outDir>
'use strict';
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

const outDir = process.argv[2];
let passed = 0;
function check(condition, name) {
  if (!condition) throw new Error('FAILED: ' + name);
  passed++;
}

async function open(browser, file) {
  const context = await browser.newContext({ offline: true, javaScriptEnabled: true });
  const page = await context.newPage();
  const requests = [];
  const violations = [];
  const consoleErrors = [];
  await page.route('**/*', (route) => { requests.push(route.request().url()); route.abort(); });
  page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
  await page.exposeFunction('__vyViolation', (v) => violations.push(v));
  await page.addInitScript(() => {
    document.addEventListener('securitypolicyviolation', (e) => {
      window.__vyViolation(e.violatedDirective + ' ' + e.blockedURI);
    });
  });
  const html = fs.readFileSync(path.join(outDir, file), 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.waitForTimeout(300);
  return { context, page, requests, violations, consoleErrors };
}

async function overlay(page) {
  return page.evaluate(() => {
    const box = document.getElementById('vy-react-error');
    return box ? box.textContent : '';
  });
}

(async () => {
  const browser = await chromium.launch();
  try {
    for (const variant of ['dev', 'prod']) {
      const t = await open(browser, `vite-app.${variant}.html`);
      const p = t.page;
      check((await overlay(p)) === '', `${variant}: no error overlay`);
      check((await p.textContent('#greeting')) === 'Hello, VY', `${variant}: TSX component with JSON data renders`);
      check((await p.$$eval('li', (els) => els.map((e) => e.textContent).join(','))) === 'editor,terminal,python,react',
        `${variant}: list renders with keys`);
      check((await p.textContent('#counter')) === 'Count: 0', `${variant}: initial state`);
      await p.click('#counter');
      await p.click('#counter');
      check((await p.textContent('#counter')) === 'Count: 2', `${variant}: useState updates on click`);
      const color = await p.$eval('#greeting', (el) => getComputedStyle(el).color);
      check(color === 'rgb(12, 34, 56)', `${variant}: imported CSS applies`);
      check((await p.textContent('#env')) === (variant === 'dev' ? 'development' : 'production'),
        `${variant}: process.env.NODE_ENV`);
      check(await p.evaluate(() => window.VyReact.started === true), `${variant}: runtime started`);
      check((await p.textContent('#eval')) === 'blocked',
        `${variant}: CSP blocks eval in page code, so the runtime works without unsafe-eval`);
      const fetchBlocked = await p.evaluate(async () => {
        try { await fetch('https://example.com/'); return false; } catch (e) { return true; }
      });
      check(fetchBlocked, `${variant}: network fetch blocked`);
      check(t.violations.filter((v) => !v.startsWith('connect-src') && !v.startsWith('script-src eval')).length === 0,
        `${variant}: no CSP violations from the runtime: ${t.violations}`);
      check(t.requests.filter((u) => !u.startsWith('https://example.com')).length === 0,
        `${variant}: page made no requests: ${t.requests}`);
      await t.context.close();
    }

    let t = await open(browser, 'react-starter.dev.html');
    check((await t.page.textContent('h1')) === 'Hello from VY', 'starter template renders');
    await t.page.click('button');
    check((await t.page.textContent('button')) === 'Clicked 1 times', 'starter button works');
    check((await overlay(t.page)) === '' && t.requests.length === 0, 'starter clean and offline');
    await t.context.close();

    t = await open(browser, 'single-file.dev.html');
    check((await t.page.textContent('#single')) === 'Single file works', 'single file renders');
    check(t.requests.length === 0, 'single file made no requests');
    await t.context.close();

    t = await open(browser, 'syntax-error.dev.html');
    let text = await overlay(t.page);
    check(/Syntax error in index\.jsx \(line \d+, column \d+\)/.test(text), 'syntax error names file, line and column: ' + text);
    await t.context.close();

    t = await open(browser, 'bad-package.dev.html');
    text = await overlay(t.page);
    check(text.includes('Package "lodash/debounce" is not available in the offline preview'), 'missing package explained: ' + text);
    await t.context.close();

    t = await open(browser, 'runtime-error.dev.html');
    text = await overlay(t.page);
    check(text.includes('Broken component exploded'), 'render error shown: ' + text);
    await t.context.close();

    t = await open(browser, 'injection.dev.html');
    check((await t.page.textContent('#tricky')).startsWith('</script><script>window.__pwned = true</script><!-- &'),
      'script-like text renders as text');
    check(await t.page.evaluate(() => window.__pwned === undefined), 'source text cannot inject script');
    check((await overlay(t.page)) === '', 'injection fixture has no error');
    await t.context.close();

    console.log(`browser-check: ${passed} assertions passed (Chromium ${browser.version()})`);
  } finally {
    await browser.close();
  }
})().catch((e) => { console.error(e.message || e); process.exit(1); });
